mapper.select:
SELECT T1.FINPROD_MARKET_ID id, T1.FINPROD_MARKET_ID text, IFNULL(FINPROD_NAME, FINPROD_ABBR) object FROM FIN_PRODUCT T1
T1.FINPROD_TYPE2 = #{assestType}
and T1.FINPROD_MARKET_ID = #{initValue}
and T1.FINPROD_MARKET_ID like concat('%',#{search},'%') or T1.FINPROD_NAME like concat('%',#{search},'%')
